#!/usr/bin/env python3
"""Check local Markdown links in docs/. Broken links: `file:line: target`. Exit 1 if any."""
import re
import sys
from pathlib import Path

DOCS = Path("docs")
INLINE = re.compile(r"\[[^\]]*\]\(([^)]+)\)")
REFDEF = re.compile(r"^\s*\[[^\]]+\]:\s*(\S+)")
SCHEME = re.compile(r"^[A-Za-z][A-Za-z0-9+.-]*:")


def targets(line):
    """Yield link targets from one line of Markdown."""
    m = REFDEF.match(line)
    if m:
        yield m.group(1)
        return
    for m in INLINE.finditer(line):
        t = m.group(1).strip()
        if t.startswith("<") and t.endswith(">"):
            t = t[1:-1]
        yield t.split()[0]  # drop any "title" part


def check(path):
    base = path.parent
    for i, line in enumerate(path.read_text(encoding="utf-8").splitlines(), 1):
        if line.lstrip().startswith("```"):
            continue  # coarse fence toggle below
        for t in targets(line):
            if SCHEME.match(t) or t.startswith("#"):
                continue  # external or in-page anchor
            if not (base / t.split("#")[0]).exists():
                yield path, i, t


def main():
    if not DOCS.is_dir():
        print(f"error: {DOCS}/ not found", file=sys.stderr)
        return 2
    broken = []
    for md in sorted(DOCS.rglob("*.md")):
        in_fence = False
        for i, line in enumerate(md.read_text(encoding="utf-8").splitlines(), 1):
            if line.lstrip().startswith("```"):
                in_fence = not in_fence
                continue
            if in_fence:
                continue
            for t in targets(line):
                if SCHEME.match(t) or t.startswith("#"):
                    continue
                if not (md.parent / t.split("#")[0]).exists():
                    broken.append(f"{md}:{i}: {t}")
    print("\n".join(broken))
    return 1 if broken else 0


if __name__ == "__main__":
    sys.exit(main())

